import React, { useEffect, useState, useMemo } from 'react';
import Layout from '@theme-original/DocItem/Layout';
import BookmarkButton from '@site/src/components/BookmarkButton';
import ShareButton from '@site/src/components/ShareButton';
import AutoScrollControl from '@site/src/components/AutoScrollControl';
import CustomAudioPlayer from '@site/src/components/CustomAudioPlayer';
import ThemeToggle from '@site/src/components/ThemeToggle';
import { useTranslation } from '@site/src/utils/translations';
import { useLocation, useHistory } from '@docusaurus/router';
import Link from '@docusaurus/Link';
import { useDoc } from '@docusaurus/plugin-content-docs/client';
import searchIndex from '@site/src/data/searchIndex.json';
import styles from './styles.module.css';

export default function DocItemLayoutWrapper(props) {
  const { t, lang, translateNumbers } = useTranslation();
  const location = useLocation();
  const history = useHistory();
  const { frontMatter, metadata } = useDoc();

  // Verification state logic
  const isVerified = useMemo(() => {
    if (!frontMatter) return false;
    if (frontMatter.verified === true) return true;
    if (Array.isArray(frontMatter.tags)) {
      return frontMatter.tags.some(tag => {
        if (typeof tag === 'string') {
          return tag.toLowerCase() === 'verified';
        } else if (tag && typeof tag === 'object' && typeof tag.label === 'string') {
          return tag.label.toLowerCase() === 'verified';
        } else if (tag && typeof tag === 'object' && typeof tag.permalink === 'string') {
          return tag.permalink.toLowerCase().endsWith('verified');
        }
        return false;
      });
    }
    if (metadata && Array.isArray(metadata.tags)) {
      return metadata.tags.some(tag => tag.label && tag.label.toLowerCase() === 'verified');
    }
    return false;
  }, [frontMatter, metadata]);

  // Modal dialog state
  const [showVerificationModal, setShowVerificationModal] = useState(false);
  const [showChapterDrawer, setShowChapterDrawer] = useState(false);
  const [chapterSearch, setChapterSearch] = useState('');
  const [showResumeToast, setShowResumeToast] = useState(false);
  const [savedScrollY, setSavedScrollY] = useState(0);
  const [dailyPathList, setDailyPathList] = useState([]);
  const [fontSize, setFontSize] = useState('medium');

  // Font size selector states
  const fontSizes = ['small', 'medium', 'large', 'xlarge'];

  const getFontSizeLabel = (key) => {
    const labels = {
      mr: { small: 'लहान', medium: 'मध्यम', large: 'मोठा', xlarge: 'अतिमोठा' },
      en: { small: 'Small', medium: 'Medium', large: 'Large', xlarge: 'Extra Large' },
      hi: { small: 'छोटा', medium: 'मध्यम', large: 'बड़ा', xlarge: 'बहुत बड़ा' }
    };
    const active = labels[lang] || labels['mr'];
    return active[key] || key;
  };

  const cleanPath = location.pathname.split('?')[0].split('#')[0];

  // Pravachan Date Selector logic
  const currentDoc = useMemo(() => {
    return searchIndex.find((doc) => doc.slug === cleanPath);
  }, [cleanPath]);

  const isPravachan = useMemo(() => {
    return currentDoc && currentDoc.category && currentDoc.category.includes('pravachane');
  }, [currentDoc]);

  const siblingPravachans = useMemo(() => {
    if (!isPravachan) return [];
    return searchIndex.filter(doc => doc.category === currentDoc.category);
  }, [isPravachan, currentDoc]);

  const parsedPravachans = useMemo(() => {
    const monthsOrder = {
      january: 1, february: 2, march: 3, april: 4, may: 5, june: 6,
      july: 7, august: 8, september: 9, october: 10, november: 11, december: 12
    };

    return siblingPravachans.map(doc => {
      if (!doc.filename) return null;
      const match = doc.filename.match(/^(\d+)([a-zA-Z]+)-([a-z]{2})$/);
      if (!match) return null;
      const day = parseInt(match[1], 10);
      const monthName = match[2].toLowerCase();
      const monthNum = monthsOrder[monthName] || 0;
      return {
        ...doc,
        day,
        monthName,
        monthNum
      };
    }).filter(Boolean);
  }, [siblingPravachans]);

  const currentParsedDate = useMemo(() => {
    if (!currentDoc || !currentDoc.filename) return null;
    const match = currentDoc.filename.match(/^(\d+)([a-zA-Z]+)-([a-z]{2})$/);
    if (!match) return null;
    return {
      day: parseInt(match[1], 10),
      monthName: match[2].toLowerCase()
    };
  }, [currentDoc]);

  const [selectedMonth, setSelectedMonth] = useState('');
  const [selectedDay, setSelectedDay] = useState('');

  useEffect(() => {
    if (currentParsedDate) {
      setSelectedMonth(currentParsedDate.monthName);
      setSelectedDay(currentParsedDate.day.toString());
    }
  }, [currentParsedDate]);

  const monthLabels = {
    hi: {
      january: 'जनवरी', february: 'फरवरी', march: 'मार्च', april: 'अप्रैल',
      may: 'मई', june: 'जून', july: 'जुलाई', august: 'अगस्त',
      september: 'सितंबर', october: 'अक्टूबर', november: 'नवंबर', december: 'दिसंबर'
    },
    mr: {
      january: 'जानेवारी', february: 'फेब्रुवारी', march: 'मार्च', april: 'एप्रिल',
      may: 'मे', june: 'जून', july: 'जुलै', august: 'ऑगस्ट',
      september: 'सप्टेंबर', october: 'ऑक्टोबर', november: 'नोव्हेंबर', december: 'डिसेंबर'
    },
    en: {
      january: 'January', february: 'February', march: 'March', april: 'April',
      may: 'May', june: 'June', july: 'July', august: 'August',
      september: 'September', october: 'October', november: 'November', december: 'December'
    }
  };

  const monthsList = [
    'january', 'february', 'march', 'april', 'may', 'june',
    'july', 'august', 'september', 'october', 'november', 'december'
  ];

  const availableDaysForMonth = useMemo(() => {
    if (!selectedMonth) return [];
    return parsedPravachans
      .filter(p => p.monthName === selectedMonth)
      .map(p => p.day)
      .sort((a, b) => a - b);
  }, [selectedMonth, parsedPravachans]);

  const handleMonthChange = (e) => {
    const newMonth = e.target.value;
    setSelectedMonth(newMonth);
    
    const available = parsedPravachans
      .filter((p) => p.monthName === newMonth)
      .sort((a, b) => a.day - b.day);
      
    if (available.length > 0) {
      const currentDayInt = parseInt(selectedDay, 10);
      const sameDayMatch = available.find((p) => p.day === currentDayInt);
      const targetDoc = sameDayMatch || available[0];
      
      setSelectedDay(targetDoc.day.toString());
      history.push(targetDoc.slug);
    } else {
      setSelectedDay('');
    }
  };

  const handleDayChange = (e) => {
    const newDay = e.target.value;
    setSelectedDay(newDay);
    
    if (newDay && selectedMonth) {
      const match = parsedPravachans.find(
        (p) => p.monthName === selectedMonth && p.day === parseInt(newDay, 10)
      );
      if (match) {
        history.push(match.slug);
      }
    }
  };

  // Daily Path logic
  const isDailyPathMode = location.search.includes('dailyPath=true');
  const dailyPathIndex = parseInt(new URLSearchParams(location.search).get('index') || '0', 10);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const storedDaily = JSON.parse(window.localStorage.getItem('dailyPath') || '[]');
    setDailyPathList(storedDaily);

    const storedFont = window.localStorage.getItem('site-font-size') || 'medium';
    setFontSize(storedFont);
    document.documentElement.setAttribute('data-font-size', storedFont);
  }, [location.pathname]);

  // Load and trigger resume scroll position
  useEffect(() => {
    if (typeof window === 'undefined') return;

    // Check if redirect from recently read card (autoresume)
    const autoresume = window.localStorage.getItem('resumeScroll');
    if (autoresume) {
      window.localStorage.removeItem('resumeScroll');
      const y = parseInt(autoresume, 10);
      if (y > 50) {
        setTimeout(() => {
          window.scrollTo({ top: y, behavior: 'smooth' });
        }, 300);
        return;
      }
    }

    // Check for manual resume toast
    const pageHistory = JSON.parse(window.localStorage.getItem('pageHistory') || '[]');
    const matching = pageHistory.find((item) => {
      const cleanItemPath = item.path.split('?')[0].split('#')[0];
      return cleanItemPath === cleanPath;
    });

    if (matching && matching.scrollPosition > 150) {
      setSavedScrollY(matching.scrollPosition);
      setShowResumeToast(true);
    } else {
      setShowResumeToast(false);
    }
  }, [location.pathname]);

  // Track scroll position in history list
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handleScroll = () => {
      try {
        const pageHistory = JSON.parse(window.localStorage.getItem('pageHistory') || '[]');
        if (!Array.isArray(pageHistory)) return;

        const updated = pageHistory.map((item) => {
          const cleanItemPath = item.path.split('?')[0].split('#')[0];
          if (cleanItemPath === cleanPath) {
            return { ...item, scrollPosition: window.scrollY };
          }
          return item;
        });
        window.localStorage.setItem('pageHistory', JSON.stringify(updated));
      } catch (e) {
        console.error(e);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [location.pathname]);

  // Automatically style shlokas containing '॥' (Devanagari double danda)
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const formatShlokas = () => {
      const paragraphs = document.querySelectorAll('article p, article h1, article h2, article h3, article blockquote');
      paragraphs.forEach((p) => {
        if (p.innerText.includes('॥')) {
          p.classList.add('shloka-verse-traditional');
        }
      });
    };
    // Run after a slight delay to ensure content is fully rendered
    const timeout = setTimeout(formatShlokas, 100);
    return () => clearTimeout(timeout);
  }, [location.pathname]);



  const handleResumeScroll = () => {
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: savedScrollY, behavior: 'smooth' });
      setShowResumeToast(false);
    }
  };

  const changeFontSize = (size) => {
    setFontSize(size);
    if (typeof window !== 'undefined') {
      window.localStorage.setItem('site-font-size', size);
      document.documentElement.setAttribute('data-font-size', size);
    }
  };

  // Chapter metadata parser for books (pothi, guru-charitra, satyanarayan)
  const isPothi = cleanPath.includes('/pothi/');
  const bookInfo = useMemo(() => {
    if (!isPothi) return null;
    const segments = cleanPath.split('/');
    if (segments.length < 3) return null;
    const parentPath = segments.slice(0, -1).join('/') + '/';

    const chapters = searchIndex.filter(item => item.slug.startsWith(parentPath));
    chapters.sort((a, b) => a.slug.localeCompare(b.slug));

    const currentIndex = chapters.findIndex(c => c.slug === cleanPath);
    if (currentIndex === -1) return null;

    return {
      chapters,
      currentIndex,
      currentChapter: chapters[currentIndex],
      total: chapters.length,
      prev: currentIndex > 0 ? chapters[currentIndex - 1] : null,
      next: currentIndex < chapters.length - 1 ? chapters[currentIndex + 1] : null,
    };
  }, [cleanPath, isPothi]);

  const filteredChapters = useMemo(() => {
    if (!bookInfo) return [];
    const query = chapterSearch.trim().toLowerCase();
    if (!query) return bookInfo.chapters;
    return bookInfo.chapters.filter((c) => c.title.toLowerCase().includes(query));
  }, [bookInfo, chapterSearch]);

  const playlistBar = (isBottom = false) => {
    if (!isDailyPathMode || dailyPathList.length === 0) return null;
    return (
      <div 
        className={styles.dailyPathPlaylistBar} 
        style={isBottom ? { marginTop: '20px', marginBottom: '0px' } : undefined}
      >
        <div className={styles.playlistProgress}>
          <span>🚩 {t('dailyPath')}: {dailyPathList[dailyPathIndex]?.title} ({translateNumbers(dailyPathIndex + 1)} / {translateNumbers(dailyPathList.length)})</span>
          <div className={styles.playlistProgressBg}>
            <div 
              className={styles.playlistProgressBar} 
              style={{ width: `${((dailyPathIndex + 1) / dailyPathList.length) * 100}%` }}
            />
          </div>
        </div>
        {dailyPathIndex < dailyPathList.length - 1 ? (
          <Link 
            className={styles.playlistNextBtn}
            to={`${dailyPathList[dailyPathIndex + 1].to}?dailyPath=true&index=${dailyPathIndex + 1}`}
          >
            ➡️ {t('nextBtn')}: {dailyPathList[dailyPathIndex + 1].title}
          </Link>
        ) : (
          <div className={styles.playlistDoneBadge}>
            🎉 {t('dailyPath')} समाप्त! जय श्री कृष्ण
          </div>
        )}
      </div>
    );
  };

  return (
    <>
      {/* Reading Controls Bar */}
      <div className={styles.readingControlsBar}>
        {/* Audio Read & Auto scroll & Actions */}
        <div className={styles.controlsRow}>
          <div className={styles.leftControls}>
            <AutoScrollControl />
            <div 
              className={`${styles.verificationBadge} ${isVerified ? styles.verifiedBadge : styles.unverifiedBadge}`}
              onClick={() => setShowVerificationModal(true)}
              role="button"
              tabIndex={0}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  setShowVerificationModal(true);
                }
              }}
              title={isVerified ? t('verifiedDetailTitle') : t('unverifiedDetailTitle')}
            >
              <span className={styles.badgeIcon}>
                {isVerified ? (
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                    <polyline points="20 6 9 17 4 12"></polyline>
                  </svg>
                ) : (
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                    <circle cx="12" cy="12" r="10"></circle>
                    <line x1="12" y1="16" x2="12" y2="12"></line>
                    <line x1="12" y1="8" x2="12.01" y2="8"></line>
                  </svg>
                )}
              </span>
              <span>{isVerified ? t('verified') : t('unverified')}</span>
            </div>
          </div>
          <div className={styles.iconActionsGroup}>
            <ShareButton className={styles.iconBtn} />
            <BookmarkButton className={styles.iconBtn} />
          </div>
        </div>

        {/* Pravachan Date Selector */}
        {isPravachan && parsedPravachans.length > 0 && (
          <div className={styles.pravachanSelectorRow} style={{ borderTop: '1px solid #ECE4D8', paddingTop: '12px' }}>
            <span className={styles.pravachanSelectorTitle}>📅 {t('selectDateTitle')}:</span>
            <div className={styles.pravachanSelectsGroup}>
              <select
                className={styles.pravachanSelect}
                value={selectedMonth}
                onChange={handleMonthChange}
              >
                {monthsList.map((monthKey) => {
                  const hasPravachans = parsedPravachans.some((p) => p.monthName === monthKey);
                  const label = (monthLabels[lang] || monthLabels['mr'])[monthKey] || monthKey;
                  return (
                    <option key={monthKey} value={monthKey} disabled={!hasPravachans}>
                      {label} {!hasPravachans ? `(${lang === 'hi' ? 'अनुपलब्ध' : (lang === 'en' ? 'Unavailable' : 'उपलब्ध नाही')})` : ''}
                    </option>
                  );
                })}
              </select>

              <select
                className={styles.pravachanSelect}
                value={selectedDay}
                onChange={handleDayChange}
                disabled={availableDaysForMonth.length === 0}
              >
                {availableDaysForMonth.length === 0 ? (
                  <option value="">{lang === 'hi' ? 'कोई प्रवचन नहीं' : (lang === 'en' ? 'No items' : 'प्रवचन नाही')}</option>
                ) : (
                  availableDaysForMonth.map((dayNum) => (
                    <option key={dayNum} value={dayNum.toString()}>
                      {translateNumbers(dayNum)}
                    </option>
                  ))
                )}
              </select>
            </div>
          </div>
        )}
      </div>

      {/* Resume toast */}
      {showResumeToast && (
        <div className={styles.resumeToast}>
          <button onClick={handleResumeScroll} className={styles.resumeBtn}>
            ⚡ {t('resumeReadPrompt')}
          </button>
          <button onClick={() => setShowResumeToast(false)} className={styles.resumeClose}>
            ✕
          </button>
        </div>
      )}

      {playlistBar(false)}

      <CustomAudioPlayer />
      <Layout {...props} />

      {playlistBar(true)}

      {/* Book chapters pagination & drawer */}
      {bookInfo && (
        <div className={styles.bookPaginationContainer}>
          <div className={styles.progressBarContainer}>
            <div className={styles.progressBarLabel}>
              {t('pageLabel')} {translateNumbers(bookInfo.currentIndex + 1)} / {translateNumbers(bookInfo.total)}
            </div>
            <div className={styles.progressBarBg}>
              <div 
                className={styles.progressBarFill} 
                style={{ width: `${((bookInfo.currentIndex + 1) / bookInfo.total) * 100}%` }}
              />
            </div>
          </div>

          <div className={styles.paginationButtons}>
            {bookInfo.prev ? (
              <Link to={bookInfo.prev.slug} className={styles.navLinkBtn}>
                ◀ {t('prevBtn')}
              </Link>
            ) : (
              <span className={styles.disabledLinkBtn}>◀ {t('prevBtn')}</span>
            )}

            <button 
              className={styles.drawerTriggerBtn}
              onClick={() => setShowChapterDrawer(!showChapterDrawer)}
            >
              📖 {t('chapterDrawer')}
            </button>

            {bookInfo.next ? (
              <Link to={bookInfo.next.slug} className={styles.navLinkBtn}>
                {t('nextBtn')} ▶
              </Link>
            ) : (
              <span className={styles.disabledLinkBtn}>{t('nextBtn')} ▶</span>
            )}
          </div>

          {/* Sibling Chapters Drawer Modal */}
          {showChapterDrawer && (
            <div className={styles.drawerBackdrop} onClick={() => setShowChapterDrawer(false)}>
              <div className={styles.drawerContent} onClick={(e) => e.stopPropagation()}>
                <div className={styles.drawerHeader}>
                  <h3>📖 {t('chapterDrawer')}</h3>
                  <button className={styles.closeDrawerBtn} onClick={() => setShowChapterDrawer(false)}>✕</button>
                </div>
                <input
                  type="text"
                  className={styles.drawerSearch}
                  placeholder={t('searchBookPlaceholder')}
                  value={chapterSearch}
                  onChange={(e) => setChapterSearch(e.target.value)}
                />
                <div className={styles.drawerList}>
                  {filteredChapters.map((item, idx) => {
                    const isActive = item.slug === cleanPath;
                    return (
                      <Link
                        key={item.slug}
                        to={item.slug}
                        className={`${styles.drawerItem} ${isActive ? styles.activeDrawerItem : ''}`}
                        onClick={() => setShowChapterDrawer(false)}
                      >
                        <span className={styles.drawerItemIndex}>{translateNumbers(idx + 1)}</span>
                        <span className={styles.drawerItemTitle}>{item.title}</span>
                      </Link>
                    );
                  })}
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Verification detail modal */}
      {showVerificationModal && (
        <div 
          className={styles.modalBackdrop} 
          onClick={() => setShowVerificationModal(false)}
        >
          <div 
            className={styles.modalContent} 
            onClick={(e) => e.stopPropagation()}
          >
            <div className={`${styles.modalIconWrapper} ${isVerified ? styles.modalIconVerified : styles.modalIconUnverified}`}>
              {isVerified ? (
                <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
                  <polyline points="22 4 12 14.01 9 11.01"></polyline>
                </svg>
              ) : (
                <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <circle cx="12" cy="12" r="10"></circle>
                  <line x1="12" y1="16" x2="12" y2="12"></line>
                  <line x1="12" y1="8" x2="12.01" y2="8"></line>
                </svg>
              )}
            </div>
            <h3 className={styles.modalTitle}>
              {isVerified ? t('verifiedDetailTitle') : t('unverifiedDetailTitle')}
            </h3>
            <p className={styles.modalDesc}>
              {isVerified ? t('verifiedDetailDesc') : t('unverifiedDetailDesc')}
            </p>
            <button 
              className={styles.modalCloseBtn}
              onClick={() => setShowVerificationModal(false)}
            >
              {t('close')}
            </button>
          </div>
        </div>
      )}
    </>
  );
}
